#include <iostream>
#include <string>
using namespace std;

class B;

class A {
public:
    int val;
    B* partner;
    A(int v) : val(v), partner(nullptr) {}
    void link(B* b);
    int sumWithPartner() const;
};

class B {
public:
    int val;
    A* partner;
    B(int v) : val(v), partner(nullptr) {}
    void link(A* a) { partner = a; a->partner = this; }
};

void A::link(B* b) {
    partner = b;
    b->partner = this;
}

int A::sumWithPartner() const {
    return partner ? val + partner->val : val;
}

int main() {
    A a(10);
    B b(32);
    cout << a.sumWithPartner() << endl;
    a.link(&b);
    cout << a.sumWithPartner() << " " << (b.partner == &a) << endl;
    B b2(5);
    A a2(7);
    b2.link(&a2);
    cout << a2.sumWithPartner() << endl;
    return 0;
}

#include <iostream>
using namespace std;

struct Node;
struct Node;

Node* pushFront(Node* head, int v);
int length(const Node* head);
void printList(const Node* head);
Node* reverseList(Node* head);
void freeList(Node* head);

struct Node {
    int data;
    Node* next;
};

Node* pushFront(Node* head, int v) {
    return new Node{v, head};
}

int length(const Node* h) {
    return h ? 1 + length(h->next) : 0;
}

void printList(const Node* h) {
    for (; h; h = h->next)
        cout << h->data << (h->next ? "->" : "");
    cout << endl;
}

Node* reverseList(Node* head) {
    Node* prev = nullptr;
    while (head) {
        Node* nx = head->next;
        head->next = prev;
        prev = head;
        head = nx;
    }
    return prev;
}

void freeList(Node* head) {
    while (head) {
        Node* nx = head->next;
        delete head;
        head = nx;
    }
}

int main() {
    Node* head = nullptr;
    for (int i = 1; i <= 5; ++i) head = pushFront(head, i * i);
    printList(head);
    cout << length(head) << endl;
    head = reverseList(head);
    printList(head);
    freeList(head);
    printList(nullptr);
    return 0;
}

#include <iostream>
