struct Folder;

class Folder {
public:
    string name;
    int size;
    vector<Folder*> kids;
    Folder(const string& n, int s) : name(n), size(s) {}
    ~Folder();
    Folder* add(Folder* f) { kids.push_back(f); return this; }
    int total() const;
    void show(int depth) const;
};

Folder::~Folder() {
    for (size_t i = 0; i < kids.size(); ++i) delete kids[i];
}

int Folder::total() const {
    int t = size;
    for (const Folder* k : kids) t += k->total();
    return t;
}

void Folder::show(int d) const {
    cout << string(d * 2, ' ') << name << " (" << total() << ")" << endl;
    for (auto k : kids) k->show(d + 1);
}

int main() {
    Folder root("root", 1);
    root.add(new Folder("a", 10))->add(new Folder("b", 20));
    Folder* c = new Folder("c", 5);
    c->add(new Folder("d", 7));
    root.add(c);
    root.show(0);
    return 0;
}

