class Engine;
class Logger;

struct Car {
    string model;
    Engine* engine;
    Logger* log;
    Car(const string& m) : model(m), engine(nullptr), log(nullptr) {}
    bool hasEngine() const { return engine != nullptr; }
};

void attach(Car& c, Engine* e);
int countAttached(const Car* cars, int n);
int countLogged(const Car* cars, int n);

class Engine {
public:
    int hp;
    Engine(int h) : hp(h) {}
};

void attach(Car& c, Engine* e) { c.engine = e; }

int countAttached(const Car* cars, int n) {
    int k = 0;
    for (int i = 0; i < n; ++i)
        if (cars[i].hasEngine()) ++k;
    return k;
}

int countLogged(const Car* cars, int n) {
    int k = 0;
    for (int i = 0; i < n; ++i)
        if (cars[i].log != nullptr) ++k;
    return k;
}

int main() {
    Car cars[3] = {Car("A"), Car("B"), Car("C")};
    Engine e1(150), e2(220);
    attach(cars[0], &e1);
    attach(cars[2], &e2);
    cout << countAttached(cars, 3) << " " << countLogged(cars, 3) << endl;
    for (int i = 0; i < 3; ++i) {
        cout << cars[i].model << ": ";
        if (cars[i].engine) cout << cars[i].engine->hp << " hp";
        else cout << "none";
        cout << endl;
    }
    return 0;
}

#include <iostream>
