using namespace std;

struct Vertex;

struct Edge {
    Vertex* from;
    Vertex* to;
    int w;
};

struct Vertex {
    int id;
    bool seen;
    vector<Edge*> out;
    Vertex(int i) : id(i), seen(false) {}
};

int dfs(Vertex* v, int& weightSum);

int dfs(Vertex* v, int& weightSum) {
    if (v->seen) return 0;
    v->seen = true;
    cout << v->id << ' ';
    int sum = v->id;
    for (Edge* e : v->out) {
        weightSum += e->w;
        sum += dfs(e->to, weightSum);
    }
    return sum;
}

int main() {
    vector<Vertex*> vs;
    for (int i = 0; i < 5; ++i) vs.push_back(new Vertex(i));
    vector<Edge*> es;
    int spec[][3] = {{0, 1, 4}, {0, 2, 1}, {2, 1, 2}, {1, 3, 5}, {3, 0, 1}};
    for (auto& s : spec) {
        Edge* e = new Edge{vs[s[0]], vs[s[1]], s[2]};
        vs[s[0]]->out.push_back(e);
        es.push_back(e);
    }
    int ws = 0;
    int total = dfs(vs[0], ws);
    cout << endl;
    cout << total << " " << ws << endl;
    for (Vertex* v : vs) cout << v->id << (v->seen ? "+" : "-") << ' ';
    cout << endl;
    for (Edge* e : es) delete e;
    for (Vertex* v : vs) delete v;
    return 0;
}

#include <iostream>
