struct TreeNode;

class BST {
    TreeNode* root;
    int count;
    TreeNode* insertRec(TreeNode* n, int k);
    void inorder(const TreeNode* n, vector<int>& out) const;
    int height(const TreeNode* n) const;
    void destroy(TreeNode* n);
public:
    BST();
    ~BST();
    void insert(int k);
    vector<int> toVector() const;
    int height() const;
    int size() const { return count; }
};

struct TreeNode {
    int key;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int k) : key(k), left(nullptr), right(nullptr) {}
};

BST::BST() : root(nullptr), count(0) {}
BST::~BST() { destroy(root); }

void BST::destroy(TreeNode* n) {
    if (!n) return;
    destroy(n->left);
    destroy(n->right);
    delete n;
}

TreeNode* BST::insertRec(TreeNode* n, int k) {
    if (!n) {
        ++count;
        return new TreeNode(k);
    }
    if (k < n->key) n->left = insertRec(n->left, k);
    else if (k > n->key) n->right = insertRec(n->right, k);
    return n;
}

void BST::insert(int k) { root = insertRec(root, k); }

void BST::inorder(const TreeNode* n, vector<int>& out) const {
    if (!n) return;
    inorder(n->left, out);
    out.push_back(n->key);
    inorder(n->right, out);
}

vector<int> BST::toVector() const {
    vector<int> v;
    inorder(root, v);
    return v;
}

int BST::height(const TreeNode* n) const {
    if (!n) return 0;
    int l = height(n->left), r = height(n->right);
    return 1 + (l > r ? l : r);
}

int BST::height() const { return height(root); }

int main() {
    BST t;
    int keys[] = {50, 30, 70, 20, 40, 60, 80, 30, 10};
    for (int k : keys) t.insert(k);
    for (int x : t.toVector()) cout << x << ' ';
    cout << endl;
    cout << t.size() << " " << t.height() << endl;
    return 0;
}

