class Subject;

class Observer {
public:
    string name;
    int lastSeen;
    Observer(const string& n) : name(n), lastSeen(-1) {}
    void update(Subject& s);
};

class Subject {
    vector<Observer*> obs;
    int state;
public:
    Subject() : state(0) {}
    void attach(Observer* o) { obs.push_back(o); }
    void setState(int s);
    int getState() const { return state; }
};

void Observer::update(Subject& s) {
    lastSeen = s.getState();
    cout << name << " sees " << lastSeen << endl;
}

void Subject::setState(int s) {
    state = s;
    for (size_t i = 0; i < obs.size(); ++i) obs[i]->update(*this);
}

int main() {
    Subject sub;
    Observer a("alpha"), b("beta");
    sub.attach(&a);
    sub.attach(&b);
    sub.attach(&a);
    sub.setState(3);
    sub.setState(8);
    cout << a.lastSeen + b.lastSeen << endl;
    return 0;
}

