class Account;

class Bank {
    int fee;
public:
    Bank(int f) : fee(f) {}
    bool transfer(Account& from, Account& to, int amt);
    void report(const Account& a) const;
};

class Account {
    string owner;
    int balance;
    friend class Bank;
public:
    Account(const string& o, int b) : owner(o), balance(b) {}
    int get() const { return balance; }
};

bool Bank::transfer(Account& from, Account& to, int amt) {
    if (from.balance < amt + fee) return false;
    from.balance -= amt + fee;
    to.balance += amt;
    return true;
}

void Bank::report(const Account& a) const {
    cout << a.owner << ": " << a.balance << endl;
}

