namespace ds {
    struct Item;
    Item* make(int w, const string& tag, Item* next);
    int totalWeight(const Item* head);
    const Item* findTag(const Item* head, const string& tag);

    struct Item {
        int w;
        string tag;
        Item* next;
    };
}

namespace ds {
    Item* make(int w, const string& tag, Item* next) {
        Item* it = new Item;
        it->w = w;
        it->tag = tag;
        it->next = next;
        return it;
    }

    int totalWeight(const Item* head) {
        if (head == nullptr) return 0;
        return head->w + totalWeight(head->next);
    }

    const Item* findTag(const Item* head, const string& tag) {
        while (head && head->tag != tag) head = head->next;
        return head;
    }
}

struct Bag {
    ds::Item* first;
    Bag() : first(nullptr) {}
    void add(int w, const string& t) { first = ds::make(w, t, first); }
};

int main() {
    Bag bag;
    bag.add(3, "nut");
    bag.add(5, "bolt");
    bag.add(9, "gear");
    cout << ds::totalWeight(bag.first) << endl;
    const ds::Item* f = ds::findTag(bag.first, "bolt");
    if (f) cout << f->tag << " " << f->w << endl;
    const ds::Item* g = ds::findTag(bag.first, "cog");
    cout << (g == nullptr ? "missing" : "found") << endl;
    while (bag.first) {
        ds::Item* nx = bag.first->next;
        delete bag.first;
        bag.first = nx;
    }
    return 0;
}

#include <iostream>
using namespace std;

class Machine;

class State {
public:
    virtual ~State() {}
    virtual const char* name() const = 0;
    virtual void step(Machine& m) = 0;
};

class Machine {
    State* cur;
    int ticks;
public:
    Machine(State* s) : cur(s), ticks(0) {}
    void set(State* s) { cur = s; }
    void run(int n);
    int getTicks() const { return ticks; }
};

class Green;
class Yellow;
class Red;

class Green : public State {
public:
    const char* name() const override { return "G"; }
    void step(Machine& m) override;
};

class Yellow : public State {
public:
    const char* name() const override { return "Y"; }
    void step(Machine& m) override;
};

class Red : public State {
public:
    const char* name() const override { return "R"; }
    void step(Machine& m) override;
};

static Green g;
static Yellow y;
static Red r;

void Green::step(Machine& m) { m.set(&y); }
void Yellow::step(Machine& m) { m.set(&r); }
void Red::step(Machine& m) { m.set(&g); }

void Machine::run(int n) {
    for (int i = 0; i < n; ++i) {
        cout << cur->name() << ' ';
        cur->step(*this);
        ++ticks;
    }
    cout << endl;
}

int main() {
    Machine m(&g);
    m.run(7);
    m.run(2);
    cout << m.getTicks() << endl;
    return 0;
}
